var i=[{title:`Ce să reduci`,text:`Cea mai simplă abordare este să faci mai puține serii grele și să rămâi mai departe de cedare timp de câteva sesiuni. Dacă faci de obicei patru serii pe exercițiu, de exemplu, poți face două serii ușoare timp de o săptămână. Reducerea volumului cu aproximativ 40–50% este o opțiune practică. Știința nu stabilește un procent exact.`},{title:`Păstrează un stimul de antrenament`,text:`O săptămână de descărcare poate include în continuare antrenament. Exercițiile cunoscute făcute cu un efort mai ușor îți păstrează coordonarea și rutina. Unii sportivi păstrează sarcini moderate și fac mai puține serii. Alții scad și sarcina, și seriile când îi îngrijorează articulațiile sau oboseala generală. Cea mai bună alegere depinde de motivul pentru care ai nevoie de descărcare.`},{title:`Când ajută`,text:`Semnele de alarmă pot include mai multe antrenamente neobișnuit de grele, scăderea performanței, oboseală care nu trece sau un sentiment tot mai puternic că nu te refaci. Aceste semne au multe cauze posibile. Nu trece cu vederea o boală sau simptome medicale ca fiind oboseală normală de antrenament. Dacă ești la început, poate ai nevoie doar de un plan obișnuit mai ușor, fără săptămâni de descărcare programate.`},{title:`Planificat sau la nevoie`,text:`Unele programe structurate folosesc o săptămână mai ușoară la fiecare patru–opt săptămâni, mai ales când volumul de muncă este mare. Acest moment este o modalitate de organizare. Dacă un program moderat merge bine pentru tine, poate nu ai nevoie de o descărcare formală, iar dacă ești sub un stres neobișnuit, una mai devreme te poate ajuta.`},{title:`Folosirea TrainUp`,text:`Săptămâna 4 din fiecare plan TrainUp este o săptămână ușoară de descărcare. Când îți regenerezi planul, acesta devine mai ușor dacă 2 din ultimele tale 3 antrenamente au fost foarte grele (RPE 9 sau mai mult) sau finalizate sub 60%. După o perioadă mai ușoară, revino la sarcinile normale pas cu pas și urmărește cum răspunzi. O săptămână liberă nu garantează că te întorci mai puternic.`}];var t=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: bazele siguranței și ale antrenamentului de forță`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Analiză sistematică a periodizării și a rezultatelor antrenamentului`,url:`https://pubmed.ncbi.nlm.nih.gov/35044672/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};